const msg = $input.first().json.message;
const text = msg.text || '';
const chatId = msg.chat.id;
const name = msg.from.first_name || 'Bhai';
const parts = text.trim().split(/\s+/);

if (!text.startsWith('/setup')) {
  return [{ json: { valid: false, chatId, name, reply: "❌ Use: /setup githubUsername leetcodeUsername" } }];
}

if (parts.length < 3) {
  return [{ json: { valid: false, chatId, name, reply: "❌ Format: /setup githubUsername leetcodeUsername\n\nExample: /setup ANUBHAV-03042004 anubhav-kumar-srivastava-abb28b239" } }];
}

return [{
  json: {
    valid: true,
    chatId,
    name,
    github_user: parts[1],
    leetcode_user: parts[2],
  }
}];

