const user = $input.first().json;
const chatId = $('Switch').item.json.message.chat.id;

if (!user.chat_id) {
  return [{
    json: {
      registered: false,
      chatId,
      reply: "⚠️ Pehle setup kar bhai!\n/setup githubUsername leetcodeUsername"
    }
  }];
}

return [{
  json: {
    registered: true,
    chatId: user.chat_id,
    name: user.name,
    github_user: user.github_user,
    leetcode_user: user.leetcode_user
  }
}];

// Get GitHub events directly from previous node
const githubEvents = $('HTTP Request').all();

// Get LeetCode data directly
const leetcodeData = $('HTTP Request1').first().json.data;

const now = new Date();
const todayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();
const weekStart = Date.now() - 7 * 24 * 60 * 60 * 1000;

const pushEvents = githubEvents.filter(e => e.json.type === 'PushEvent');
const todayCommits = pushEvents
  .filter(e => new Date(e.json.created_at).getTime() >= todayStart)
  .reduce((sum, e) => sum + (e.json.payload?.commits?.length || 1), 0);
const weekCommits = pushEvents
  .filter(e => new Date(e.json.created_at).getTime() >= weekStart)
  .reduce((sum, e) => sum + (e.json.payload?.commits?.length || 1), 0);
const recentRepo = pushEvents[0]?.json?.repo?.name?.split('/')[1] || 'None';
const lastActive = githubEvents[0]?.json?.created_at
  ? new Date(githubEvents[0].json.created_at).toLocaleDateString('en-IN')
  : 'Never';

const lc = leetcodeData.matchedUser;
const recentSubs = leetcodeData.recentAcSubmissionList || [];
const stats = lc.submitStats.acSubmissionNum;
const totalSolved = stats.find(s => s.difficulty === 'All')?.count || 0;
const easy = stats.find(s => s.difficulty === 'Easy')?.count || 0;
const medium = stats.find(s => s.difficulty === 'Medium')?.count || 0;
const hard = stats.find(s => s.difficulty === 'Hard')?.count || 0;
const streak = lc.userCalendar?.streak || 0;

const todayTimestamp = Math.floor(todayStart / 1000);
const solvedToday = recentSubs.filter(s => parseInt(s.timestamp) >= todayTimestamp).length;
const weekTimestamp = Math.floor(weekStart / 1000);
const solvedThisWeek = recentSubs.filter(s => parseInt(s.timestamp) >= weekTimestamp).length;

const isLazy = todayCommits === 0 && solvedToday === 0;
const xp = (todayCommits * 30) + (solvedToday * 50);
const chatId = $('Code in JavaScript1').first().json.chatId;
const name = $('Code in JavaScript1').first().json.name;

return [{
  json: {
    chatId,
    name,
    github: { todayCommits, weekCommits, lastActive, recentRepo },
    leetcode: { totalSolved, easy, medium, hard, solvedToday, solvedThisWeek, streak },
    isLazy,
    xp
  }
}];

